// 诡仙录（Ghost MUD）· 素材文件
// 文件：ghost_npc_encounters.js
// 用途：为 rebuild_*.js 执行层提供随机事件/叙事素材储备
// 引擎：不直接加载。随机事件由 integration_v2.js 从 rebuild_* 文件
//       中的事件池索引，本文件为事件池提供可替换的叙事内容
// 门派体系：20势力（武修6+灵修6+NPC门派8），详见 narrative_design.md
// 叙事风格：金庸皮+克苏鲁骨 — 古风江湖外表，灵异恐怖内核
// ═══════════════════════════════════════════════════════════

