      "title": "香客",
      "desc": "中年妇人在佛前跪拜，口中念念有词——但念的不是经文，像是反反复复只念一个人的名字。起身看见你：「你是外乡来的吧？求求你——我儿子上次出城就没消息了，他说去{N_room}淘二手法器身。求你帮我去看一眼？」她的手攥着你的袖子，你发现她的指甲是黑的——不是涂的。",
